                .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(date))
                .max(Comparator.comparing(Rate::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())));
    }

    private static boolean ended(Rate rate, LocalDate date) {
        return rate.getToDate() != null && rate.getToDate().isBefore(date);
    }

    /** The cap in force on the sheet's today: the most a person's due-total comes to; null when there is none. */
    public BigDecimal cap() {
        return settings.cap(today);
    }

    /** A due-total held to the cap: the cap when the sum is above it; as it is otherwise, or when n/a (null). */
    public BigDecimal capped(BigDecimal sum) {
        BigDecimal cap = cap();
        return sum == null || cap == null || sum.compareTo(cap) <= 0 ? sum : cap;
    }

    /** What a due-total's sum is above the cap: 0.00 when it is not, or when n/a (null). */
    public BigDecimal excess(BigDecimal sum) {
        BigDecimal cap = cap();
        return sum == null || cap == null || sum.compareTo(cap) <= 0 ? BigDecimal.ZERO : sum.subtract(cap);
    }

    /**
     * A due-total held to the cap less the person's cut total (not below 0.00): that when the sum is above it; as it
     * is otherwise, or when n/a (null).
     */
    public BigDecimal capped(BigDecimal sum, BigDecimal cut) {
        BigDecimal cap = cap();
        if (sum == null || cap == null) {
            return sum;
        }
        BigDecimal room = cap.subtract(cut).max(BigDecimal.ZERO);
        return sum.compareTo(room) <= 0 ? sum : room;
    }

    /**
     * What a due-total's sum loses to the cap less the person's cut total (see {@link #capped(BigDecimal, BigDecimal)}):
     * the sum plus the cut total above the cap, but never more than the sum; 0.00 when it is not above, or when
     * n/a (null).
     */
    public BigDecimal excess(BigDecimal sum, BigDecimal cut) {
        return sum == null ? BigDecimal.ZERO : sum.subtract(capped(sum, cut));
    }

    /** The percent in force for the grade on the sheet's today; null when none is. */
    public BigDecimal current(String grade) {
        return on(grade, today);
    }

    /**
     * How the figures of a claim whose rounding goes by the date round: by the rounding mode in force on
     * that date when one is; otherwise half up when it is before the policy date (the sheet's today when
     * none is set), half to even on or after it.
     */
    public RoundingMode rounding(LocalDate roundsBy) {
        RoundingMode mode = settings.rounding(roundsBy);
        if (mode != null) {
            return mode;
        }
        LocalDate policy = policyDate == null ? today : policyDate;
        return roundsBy.isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /**
     * The rate figure of an amount dated on the date for the grade: the amount at the rate in force then,
     * rounded by the date, with no floor; null when no rate is.
     */
    public BigDecimal figure(BigDecimal amount, String grade, LocalDate date) {
        return figure(amount, grade, date, null);
    }

    /** The rate figure of the claim with the id given, as {@link #figure(BigDecimal, String, LocalDate)} at the rate in force for it, see {@link #on(String, LocalDate, Long)}. */
    public BigDecimal figure(BigDecimal amount, String grade, LocalDate date, Long claimId) {
        return RateService.due(amount, on(grade, date, claimId), rounding(date));
    }

    /** A live due held up to the floor in force on the date: the greater of the two; null when the due is. */
    public BigDecimal floored(BigDecimal due, LocalDate date) {
        BigDecimal floor = settings.floor(date);
        return due == null || floor == null || due.compareTo(floor) >= 0 ? due : floor;
    }

    /**
     * The late charge on a figure of a claim due by the due-by: for every full 30 days from its due-by to the
     * sheet's today, the late percent in force on that boundary date (the due-by plus 30, 60, 90 ... days) of
     * the figure plus the charges of the boundaries before it (compounding), each rounded by the date its claim's rounding goes by, added up; a boundary whose percent is
     * 0.00 adds nothing. 0.00 when not a full 30 days overdue.
     */
    public BigDecimal lateCharge(BigDecimal figure, LocalDate dueBy, LocalDate roundsBy) {
        long periods = dueBy.isBefore(today) ? ChronoUnit.DAYS.between(dueBy, today) / LATE_PERIOD_DAYS : 0;
        RoundingMode rounding = rounding(roundsBy);
        BigDecimal charge = BigDecimal.ZERO.setScale(2);
        for (long n = 1; n <= periods; n++) {
            BigDecimal pct = settings.latePct(dueBy.plusDays(n * LATE_PERIOD_DAYS));
            if (pct.signum() != 0) {
                charge = charge.add(RateService.due(figure.add(charge), pct, rounding));
            }
        }
        return charge;
    }
}
