        rows.tables().getOrDefault(scope.table(), List.of()).forEach(row -> insert(scope.table(), row));
    }
    jdbc.update("UPDATE sheet SET today = ? WHERE id = ?", rows.sheet().get("TODAY"), sheetId);
}

