reviewSla: string | null;
pendingSla: string | null;
/** While both are set, a person whose score is at or above the high one is HIGH, at or above the mid one MID, else LOW; null when blank. Whole numbers, not dated. */
scoreMid: string | null;
scoreHigh: string | null;
/** While on, changing the sheet's today writes everyone's score on the day being left; null when off. Not dated. */
scoreLog: string | null;
/** A person may have at most this many OPEN or PENDING claims; null when there is no maximum. A whole number, not dated. */
maxOpen: string | null;
/** The kinds of proof (receipt, photo), comma separated, a claim above the proof threshold needs one of each of; null when none. Not dated. */
proofKinds: string | null;
/** The grade quick-add and an import line with a blank grade give a new person; null when blank (A). Not dated. */
defaultGrade: string | null;
    <p>Alert threshold <strong data-testid="setting-alert-threshold-current">{{ (alertThreshold() ?? '') | figure }}</strong></p>
    <p>Escalate after (days) <strong data-testid="setting-escalate-after-current">{{ escalateAfter() ?? '' }}</strong></p>
    <p>Review SLA (days) <strong data-testid="setting-review-sla-current">{{ reviewSla() ?? '' }}</strong></p>
    <p>Pending SLA (days) <strong data-testid="setting-pending-sla-current">{{ pendingSla() ?? '' }}</strong></p>
    <p>Score mid threshold <strong data-testid="setting-score-mid-current">{{ scoreMid() ?? '' }}</strong></p>
    <p>Score high threshold <strong data-testid="setting-score-high-current">{{ scoreHigh() ?? '' }}</strong></p>
    <p>Score log <strong data-testid="setting-score-log-current">{{ scoreLog() ?? '' }}</strong></p>
    <p>Max open claims per person <strong data-testid="setting-max-open-current">{{ maxOpen() ?? '' }}</strong></p>
    <p>Proof kinds <strong data-testid="setting-proof-kinds-current">{{ proofKinds() ?? '' }}</strong></p>
    <p>Default grade <strong data-testid="setting-default-grade-current">{{ defaultGrade() ?? '' }}</strong></p>
    <p>Parent sheet <strong data-testid="setting-parent-current">{{ parent() ?? '' }}</strong></p>
  this.pendingSlaTouched = false;
  this.scoreMid.set(settings.scoreMid);
  this.scoreMidInput.set(settings.scoreMid ?? '');
  this.scoreMidTouched = false;
  this.scoreHigh.set(settings.scoreHigh);
  this.scoreHighInput.set(settings.scoreHigh ?? '');
  this.scoreHighTouched = false;
  this.scoreLog.set(settings.scoreLog);
  this.scoreLogInput.set(settings.scoreLog ?? '');
  this.scoreLogTouched = false;
  this.maxOpen.set(settings.maxOpen);
  this.maxOpenInput.set(settings.maxOpen ?? '');
  this.maxOpenTouched = false;
  this.proofKinds.set(settings.proofKinds);
  this.proofKindsInput.set(settings.proofKinds ?? '');
  this.proofKindsTouched = false;
  this.defaultGrade.set(settings.defaultGrade);
/** For a claim split off another, the number of the claim it was split from, as shown; null otherwise. */
splitFrom: string | null;
/** The number of the bulk settle batch that settled the claim (to SETTLED or PENDING); null when settled one at a time or never. */
settleBatch: number | null;
/** The user whose open editor locks the claim for everyone else; null when no editor holds it. */
lockedBy: string | null;
/** Whether the claim was added while its period was soft-closed. */
lateEntry: boolean;
/** Whether the claim is REVIEW and its review day plus the sheet's review SLA is before the sheet's today. */
reviewLate: boolean;
pendingLate: boolean;
/** Whether a steward waived the claim's late charge: it then bears none, whatever its overdue state. */
waived: boolean;
/** Whether the claim is held: it still counts in every total; a hold no longer leaves it out. */
        <span>Deferred until <span data-testid="claim-deferred-until">{{ c.deferredUntil ?? '' }}</span></span>
        <span>Proofs <span data-testid="claim-proofs">{{ c.proofs }}</span></span>
        <span>Receipts <span data-testid="claim-proofs-receipt">{{ c.proofsReceipt }}</span></span>
        <span>Photos <span data-testid="claim-proofs-photo">{{ c.proofsPhoto }}</span></span>
        <span>Split from <span data-testid="claim-split-from">{{ c.splitFrom ?? '' }}</span></span>
        <span>Batch <span data-testid="claim-batch">{{ c.settleBatch ?? '' }}</span></span>
        <span>Late entry <span data-testid="claim-late-entry">{{ c.lateEntry ? 'yes' : 'no' }}</span></span>
        <span>Review late <span data-testid="claim-review-late">{{ c.reviewLate ? 'yes' : 'no' }}</span></span>
        <span>Pending late <span data-testid="claim-pending-late">{{ c.pendingLate ? 'yes' : 'no' }}</span></span>
        <span>Waived <span data-testid="claim-waived">{{ c.waived ? 'yes' : 'no' }}</span></span>
        <button type="button" data-testid="claim-waive" (click)="waive(c)">
          Waive late charge<span class="visually-hidden"> of claim {{ c.amount }} {{ c.date }}</span>
        </button>

